def close(self, timeout: float) -> dict[str, Any]:
        process = self.process
        escalation = "already-exited"
        if process is not None and process.poll() is None:
            try:
                response = self.request({"id": "shutdown", "method": "shutdown"}, min(timeout, 2.0))
                escalation = "shutdown" if response.get("ok") else "shutdown-error"
            except Exception:
                escalation = "shutdown-error"
            try:
                process.wait(timeout=max(0.2, timeout / 2))
            except subprocess.TimeoutExpired:
                process.terminate()
                escalation = "terminate"
                try:
                    process.wait(timeout=max(0.2, timeout / 3))
                except subprocess.TimeoutExpired:
                    process.kill()
                    escalation = "kill"
                    process.wait(timeout=max(0.2, timeout / 3))
        if process is not None:
            for stream in (process.stdin, process.stdout, process.stderr):
                if stream is not None:
                    try:
                        stream.close()
                    except OSError:
                        pass
        for reader in (self.stdout_reader, self.stderr_reader):
            if reader is not None:
                reader.join(timeout=2.0)
        exit_code = process.returncode if process is not None else None
        pid = process.pid if process is not None else None
        stderr = list(self.stderr_lines or [])[-20:]
        self.process = None
        self.stdout_queue = None
        self.stdout_reader = None
        self.stderr_reader = None
        self.stderr_lines = None
        self.pending = 0
        return {"escalation": escalation, "server_pid": pid, "exit_code": exit_code, "stderr": stderr}

"""Machine-local clickable links for source files and Obsidian notes."""

from __future__ import annotations

import json
import os
from pathlib import Path, PurePosixPath
from typing import Any
from urllib.parse import quote, unquote, urlparse

from .common import CkbError, json_load, json_write, path_inside


SOURCE_EDITORS = {"vscode", "vscode-insiders", "file", "custom-template"}


class SourceLinkRenderer:
    """Validate one opener config and cache resolved repository paths.

    Retrieval may render several entities from the same file.  The public
    one-shot helpers below intentionally preserve their old behavior, while a
    long-lived renderer avoids repeating Windows ``resolve`` and
    ``_getfinalpathname`` work for every candidate.
    """

    def __init__(self, config: dict[str, Any], *, trusted_relative_paths: bool = False) -> None:
        self.config = validate_local_openers(config)
        root_value = self.config.get("working_repo_root")
        if self.config.get("source_view") == "baseline" and self.config.get("baseline_snapshot_root"):
            root_value = self.config["baseline_snapshot_root"]
        self.root = Path(str(root_value)).resolve()
        self.trusted_relative_paths = trusted_relative_paths
        self._absolute_paths: dict[str, Path] = {}

    @property
    def cache_size(self) -> int:
        return len(self._absolute_paths)

    def absolute_path(self, relative_path: str) -> Path:
        cached = self._absolute_paths.get(relative_path)
        if cached is not None:
            return cached
        relative = PurePosixPath(relative_path)
        if relative.is_absolute() or ".." in relative.parts:
            raise CkbError(f"source path is outside the repository: {relative_path}")
        joined = self.root.joinpath(*relative.parts)
        if self.trusted_relative_paths:
            # Machine retrieval only supplies paths from the audited source
            # manifest.  Absolute and parent components were rejected above,
            # so the lexical path is repository-bounded without another
            # filesystem canonicalization for every selected entity.
            path = joined
        else:
            path = joined.resolve()
            if not path_inside(path, self.root):
                raise CkbError(f"source path is outside the selected source root: {relative_path}")
        self._absolute_paths[relative_path] = path
        return path

    def uri(self, relative_path: str, line: int, column: int = 1) -> str:
        absolute = self.absolute_path(relative_path)
        encoded = quote(absolute.as_posix(), safe="/:")
        editor = self.config["source_editor"]
        if editor == "vscode":
            return f"vscode://file/{encoded}:{int(line)}:{int(column)}"
        if editor == "vscode-insiders":
            return f"vscode-insiders://file/{encoded}:{int(line)}:{int(column)}"
        if editor == "file":
            prefix = "file:///" if os.name == "nt" else "file://"
            return prefix + encoded
        return str(self.config["custom_template"]).format(
            absolute_path=encoded,
            line=int(line),
            column=int(column),
        )

    def markdown_link(self, relative_path: str, start_line: int, end_line: int) -> str:
        uri = self.uri(relative_path, start_line, 1)
        label = f"打开源码：{relative_path} 第 {start_line} 行"
        suffix = f"  `{relative_path}:{start_line}-{end_line}`" if self.config.get("show_source_range", True) else ""
        return f"[{label}]({uri}){suffix}"


def default_openers(repository_root: Path, snapshot_root: Path | None = None) -> dict[str, Any]:
    return {
        "schema_version": 1,
        "source_editor": "vscode" if os.name == "nt" else "file",
        "working_repo_root": str(repository_root.resolve()),
        "baseline_snapshot_root": str(snapshot_root.resolve()) if snapshot_root else None,
        "source_view": "working",
        "show_source_range": True,
        "custom_template": None,
    }


def ensure_local_openers(output: Path, repository_root: Path, snapshot_root: Path | None = None) -> dict[str, Any]:
    path = output / "local-openers.json"
    if path.is_file():
        return validate_local_openers(json_load(path))
    value = default_openers(repository_root, snapshot_root)
    json_write(path, value)
    return value


def validate_local_openers(value: dict[str, Any]) -> dict[str, Any]:
    if not isinstance(value, dict) or value.get("schema_version") != 1:
        raise CkbError("local-openers.json must use schema_version 1")
    editor = value.get("source_editor")
    if editor not in SOURCE_EDITORS:
        raise CkbError(f"unsupported source editor: {editor}")
    root = Path(str(value.get("working_repo_root", ""))).resolve()
    if not root.is_dir():
        raise CkbError(f"working repository root is missing: {root}")
    source_view = value.get("source_view", "working")
    if source_view not in {"working", "baseline"}:
        raise CkbError("source_view must be working or baseline")
    template = value.get("custom_template")
    if editor == "custom-template" and (
        not isinstance(template, str)
        or "{absolute_path}" not in template
        or "{line}" not in template
        or "{column}" not in template
    ):
        raise CkbError("custom source-link template requires {absolute_path}, {line}, and {column}")
    return {
        "schema_version": 1,
        "source_editor": editor,
        "working_repo_root": str(root),
        "baseline_snapshot_root": value.get("baseline_snapshot_root"),
        "source_view": source_view,
        "show_source_range": bool(value.get("show_source_range", True)),
        "custom_template": template,
    }


def update_local_openers(
    output: Path,
    repository_root: Path,
    *,
    editor: str = "vscode",
    source_view: str = "working",
    custom_template: str | None = None,
) -> dict[str, Any]:
    state_path = output / "state.json"
    if not state_path.is_file():
        raise CkbError(f"state.json does not exist: {state_path}")
    state = json_load(state_path)
    snapshot_root = (state.get("source_snapshot") or {}).get("root")
    value = default_openers(repository_root, Path(snapshot_root) if snapshot_root else None)
    value.update({"source_editor": editor, "source_view": source_view, "custom_template": custom_template})
    value = validate_local_openers(value)
    json_write(output / "local-openers.json", value)
    return value


def source_absolute_path(config: dict[str, Any], relative_path: str) -> Path:
    return SourceLinkRenderer(config).absolute_path(relative_path)


def source_uri(config: dict[str, Any], relative_path: str, line: int, column: int = 1) -> str:
    return SourceLinkRenderer(config).uri(relative_path, line, column)


def source_markdown_link(config: dict[str, Any], relative_path: str, start_line: int, end_line: int) -> str:
    return SourceLinkRenderer(config).markdown_link(relative_path, start_line, end_line)


def obsidian_open_uri(path: Path) -> str:
    return "obsidian://open?path=" + quote(str(path.resolve()), safe="")


def audit_source_uri(config: dict[str, Any], uri: str, relative_path: str, line: int) -> str | None:
    expected = source_uri(config, relative_path, line, 1)
    if uri != expected:
        return "source-uri-does-not-match-source-location"
    parsed = urlparse(uri)
    if parsed.scheme not in {"vscode", "vscode-insiders", "file", "cursor", "idea"}:
        return "source-uri-scheme-is-not-allowed"
    if parsed.scheme.startswith("vscode"):
        decoded = unquote(parsed.path)
        if f":{int(line)}:1" not in decoded:
            return "source-uri-line-is-missing"
    return None

def uri(self, relative_path: str, line: int, column: int = 1) -> str:
        absolute = self.absolute_path(relative_path)
        encoded = quote(absolute.as_posix(), safe="/:")
        editor = self.config["source_editor"]
        if editor == "vscode":
            return f"vscode://file/{encoded}:{int(line)}:{int(column)}"
        if editor == "vscode-insiders":
            return f"vscode-insiders://file/{encoded}:{int(line)}:{int(column)}"
        if editor == "file":
            prefix = "file:///" if os.name == "nt" else "file://"
            return prefix + encoded
        return str(self.config["custom_template"]).format(
            absolute_path=encoded,
            line=int(line),
            column=int(column),
        )

"""Human-first navigation for durable Agent work records.

The index treats every analysis, change, pitfall, experiment, and session note
uniformly.  It never receives task-specific keywords or a hand-picked result
set; titles and one-line descriptions come from the existing reviewed notes.
"""

from __future__ import annotations

from pathlib import Path
import re
from typing import Any

from .common import CkbError, json_write
from .obsidian import NOTE_DIRECTORIES


WORK_RECORD_INDEX = "RECORDS.md"
WORK_RECORD_TAG = "#类型/导览"
LONG_HEX = re.compile(r"(?<![0-9A-Fa-f])[0-9A-Fa-f]{40,}(?![0-9A-Fa-f])")
CHINESE_RE = re.compile(r"[\u3400-\u9fff]")
SECTIONS = {
    "analysis": ("分析与决策", "查找已经形成的结论、方案比较、边界和后续判断。"),
    "changes": ("实现与变更", "查找已经修改的内容、修改原因、验证结果和交付范围。"),
    "experiments": ("实验与量化结果", "查找测试协议、性能数字、对照结果和适用限制。"),
    "pitfalls": ("踩坑与限制", "查找失败原因、环境差异、规避条件和复现入口。"),
    "sessions": ("会话与任务过程", "查找一次任务的目标、执行范围、结果和待继续事项。"),
}
SECTION_ORDER = ("analysis", "changes", "experiments", "pitfalls", "sessions")


def _contains_chinese(value: str) -> bool:
    return len(CHINESE_RE.findall(value)) >= 2


def _title(text: str, fallback: str) -> str:
    first = text.splitlines()[0] if text else ""
    return first.removeprefix("# ").strip() or fallback


def _plain_text(value: str) -> str:
    value = re.sub(r"!\[[^\]]*\]\([^)]*\)", "", value)
    value = re.sub(r"\[([^\]]+)\]\([^)]*\)", r"\1", value)
    value = re.sub(r"\[\[([^\]|#]+)(?:[|#][^\]]*)?\]\]", r"\1", value)
    value = re.sub(r"[`*>#]", "", value)
    return re.sub(r"\s+", " ", value).strip()


def _first_narrative(text: str) -> str:
    if "\n## 后续补充\n" in text:
        text = text.rsplit("\n## 后续补充\n", 1)[1]
    paragraphs: list[str] = []
    current: list[str] = []
    fenced = False
    for raw in text.splitlines()[1:]:
        line = raw.strip()
        if line.startswith("```"):
            fenced = not fenced
            continue
        if fenced:
            continue
        if not line:
            if current:
                paragraphs.append(" ".join(current))
                current = []
            continue
        if line.startswith(("#", "标签：", "- [[", "- [打开源码：", "|", "<!--")):
            continue
        if re.match(r"^[-*+]\s+", line) or re.match(r"^\d+[.)]\s+", line):
            continue
        current.append(line)
    if current:
        paragraphs.append(" ".join(current))
    for paragraph in paragraphs:
        value = _plain_text(paragraph)
        if not _contains_chinese(value):
            continue
        sentence = re.match(r"^(.{12,140}?[。！？；])(?:\s|$)", value)
        if sentence:
            return sentence.group(1)
        if len(value) <= 120:
            return value
        return value[:117].rstrip("，、；： ") + "……"
    return "本记录保存一次经过审阅的任务结论、实现变化或验证结果。"


def collect_work_records(root: Path) -> list[dict[str, Any]]:
    records: list[dict[str, Any]] = []
    seen_titles: set[str] = set()
    for directory in SECTION_ORDER:
        for path in sorted((root / directory).glob("*.md"), key=lambda item: item.name.casefold()):
            text = path.read_text(encoding="utf-8-sig")
            title = _title(text, path.stem)
            if title == "工作记录导览":
                raise CkbError("work record title conflicts with generated navigation: 工作记录导览")
            if title in seen_titles:
                raise CkbError(f"work record title must be unique: {title}")
            seen_titles.add(title)
            records.append(
                {
                    "title": title,
                    "directory": directory,
                    "file": path.relative_to(root).as_posix(),
                    "summary": _first_narrative(text),
                }
            )
    return records


def render_work_record_index(root: Path) -> tuple[str, list[dict[str, Any]]]:
    records = collect_work_records(root)
    lines = [
        "# 工作记录导览",
        "",
        f"标签：{WORK_RECORD_TAG}",
        "",
        "> 这里按任务目的汇总全部分析、变更、实验、踩坑和会话记录；每条记录都使用同一套确定性规则进入导览。",
        "",
        "## 先按任务选择",
        "",
        "- 需要理解已有结论或设计边界时，查看“分析与决策”。",
        "- 需要确认已经修改什么以及如何验证时，查看“实现与变更”。",
        "- 需要比较性能、召回、上下文或其他量化结果时，查看“实验与量化结果”。",
        "- 需要避开已知失败和环境差异时，查看“踩坑与限制”。",
        "- 需要恢复一次任务的上下文时，查看“会话与任务过程”。",
        "",
        "## 快速查找",
        "",
        "在 Obsidian 中先使用本页标题浏览；记录较多时，再用核心搜索输入任务中的两个或三个稳定关键词。需要定位源码时，转到首页的确定性检索入口。",
        "",
    ]
    from .research_gaps import gap_navigation_counts

    gap_counts = gap_navigation_counts(root)
    if gap_counts is not None:
        lines.extend(
            [
                "## 研究缺口与待补来源",
                "",
                "这里仅汇总待验证主张，不把缺口写成已确认事实，也不为每个缺口创建页面。使用 `gaps list` 查看机器记录和证据路径。",
                "",
                f"- 当前共 {gap_counts['total']} 项：待补证据 {gap_counts['open']} 项，暂缓 {gap_counts['deferred']} 项，已关闭 {gap_counts['resolved']} 项。",
                "",
            ]
        )
    by_directory = {directory: [] for directory in NOTE_DIRECTORIES}
    for record in records:
        by_directory[record["directory"]].append(record)
    for directory in SECTION_ORDER:
        heading, description = SECTIONS[directory]
        lines.extend([f"## {heading}", "", description, ""])
        items = by_directory[directory]
        if items:
            lines.extend(f"- [[{item['title']}]] — {item['summary']}" for item in items)
        else:
            lines.append("- 当前没有这一类记录。")
        lines.append("")
    return "\n".join(lines).rstrip() + "\n", records


def write_work_record_index(root: Path) -> dict[str, Any]:
    text, records = render_work_record_index(root)
    target = root / WORK_RECORD_INDEX
    target.write_text(text, encoding="utf-8", newline="\n")
    return {
        "status": "ready",
        "file": str(target.resolve()),
        "record_count": len(records),
        "sections": {directory: sum(1 for item in records if item["directory"] == directory) for directory in NOTE_DIRECTORIES},
    }


def refresh_work_record_index(output: Path) -> dict[str, Any]:
    markdown = output / "markdown"
    human = output / "human"
    if not markdown.is_dir() or not human.is_dir():
        raise CkbError("work record navigation requires human and markdown roots")
    text, records = render_work_record_index(markdown)
    for root in (markdown, human):
        (root / WORK_RECORD_INDEX).write_text(text, encoding="utf-8", newline="\n")
    audit = audit_work_record_index(output)
    json_write(output / "workspace-meta/work-record-index-audit.json", audit)
    if audit["status"] != "passed":
        raise CkbError(f"work record navigation audit failed: {audit['errors'][:10]}")
    return {"status": "passed", "record_count": len(records), "audit": audit}


def audit_work_record_root(root: Path) -> dict[str, Any]:
    errors: list[dict[str, Any]] = []
    target = root / WORK_RECORD_INDEX
    try:
        expected, records = render_work_record_index(root)
    except CkbError as exc:
        return {"status": "failed", "record_count": 0, "errors": [{"reason": "work-record-collection", "detail": str(exc)}]}
    if not target.is_file():
        errors.append({"reason": "work-record-index-missing"})
        actual = ""
    else:
        actual = target.read_text(encoding="utf-8-sig")
        if actual != expected:
            errors.append({"reason": "work-record-index-stale"})
        if actual.startswith("---\n"):
            errors.append({"reason": "work-record-index-frontmatter"})
        if actual.count(WORK_RECORD_TAG) != 1:
            errors.append({"reason": "work-record-index-tag", "count": actual.count(WORK_RECORD_TAG)})
        if LONG_HEX.search(actual):
            errors.append({"reason": "work-record-index-hash"})
    expected_titles = {item["title"] for item in records}
    linked_titles = set(re.findall(r"\[\[([^\]|#]+)", actual))
    if linked_titles != expected_titles:
        errors.append(
            {
                "reason": "work-record-index-link-set",
                "missing": sorted(expected_titles - linked_titles),
                "extra": sorted(linked_titles - expected_titles),
            }
        )
    missing_summaries = [item["title"] for item in records if not _contains_chinese(item["summary"])]
    if missing_summaries:
        errors.append({"reason": "work-record-index-summary-not-chinese", "titles": missing_summaries})
    return {
        "status": "passed" if not errors else "failed",
        "record_count": len(records),
        "linked_record_count": len(linked_titles & expected_titles),
        "section_counts": {directory: sum(1 for item in records if item["directory"] == directory) for directory in NOTE_DIRECTORIES},
        "errors": errors,
    }


def audit_work_record_index(output: Path) -> dict[str, Any]:
    markdown = output / "markdown"
    human = output / "human"
    result = audit_work_record_root(markdown)
    errors = list(result["errors"])
    left = markdown / WORK_RECORD_INDEX
    right = human / WORK_RECORD_INDEX
    if not left.is_file() or not right.is_file():
        errors.append({"reason": "work-record-index-mirror-missing"})
    elif left.read_bytes() != right.read_bytes():
        errors.append({"reason": "work-record-index-mirror-differs"})
    return {**result, "status": "passed" if not errors else "failed", "errors": errors}

def audit_work_record_index(output: Path) -> dict[str, Any]:
    markdown = output / "markdown"
    human = output / "human"
    result = audit_work_record_root(markdown)
    errors = list(result["errors"])
    left = markdown / WORK_RECORD_INDEX
    right = human / WORK_RECORD_INDEX
    if not left.is_file() or not right.is_file():
        errors.append({"reason": "work-record-index-mirror-missing"})
    elif left.read_bytes() != right.read_bytes():
        errors.append({"reason": "work-record-index-mirror-differs"})
    return {**result, "status": "passed" if not errors else "failed", "errors": errors}
